SELECT l.lot_id, l.lot_path, l.material_code, m.display_name AS material_name, l.work_order_number, l.line_code, l.quantity, l.status AS lot_status, q.quality_id, COALESCE(q.defect_code, '') AS defect_code, COALESCE(q.severity, '') AS severity, COALESCE(q.result, '') AS quality_result, COALESCE(q.recorded_at::text, '') AS recorded_at FROM mes_genealogy_lot l JOIN mes_genealogy_material m ON m.material_code = l.material_code LEFT JOIN mes_genealogy_quality q ON q.lot_id = l.lot_id ORDER BY l.lot_id, q.recorded_at
